/** The skill's usecase engine, router and Mermaid reader, sharing one TOKENS (its text measurements). */
export function usecaseEngine(TOKENS: unknown): unknown {
// ── assets/types/usecase/engine.js ──
// Use case layout engine. Pure JS, no DOM. Run by the page (Tidy, edits, saved-page routes) and by
// scripts/run_engine.mjs (--layout), so both use this one implementation. Plan: dev/plans/plan-usecase.md.
//
// Input:  title?, subjects?[{id,name,collapsed?}], actors[{id,name,kind?,side?,parent?}],
//         useCases[{id,name,subject?,color?,level?,extensionPoints?,parent?}],
//         links[{id,type: association|include|extend, from, to, condition?}]
// Output (derived, written in place; units are canvas px, top-left origin):
//         actors[].x,y,w,h,_side,_figW,_figH   the whole actor (round avatar, name and keyword below); _figW/_figH = the avatar
//                                              (a circle at the top centre of the actor, for every kind)
//         useCases[].x,y,w,h,_lines,_compH,_hidden   ellipse box (compartment included), name wrapped to <= 2 lines,
//                                              extension-points compartment height, true inside a collapsed subject (w = h = 0)
//         subjects[].x,y,w,h,_titleH           boundary box (data._subjects for an implicit `_main` subject); subjects[].fw,fh (saved,
//                                              set by dragging the frame's corner) are a minimum width and height
//         links[].points,labelBox,_hidden      2 points straight, 3 points a quadratic curve (middle = control); [] when hidden
//         data._parents[{from,to,kind,points}] one line per `parent` (to = the parent, the triangle sits at the last point)
//         data.canvas {width,height,crossings,hits}
// layoutDiagram(data): full layout. routeDiagram(data): keeps every x/y, recomputes the rest (lays out when one is missing).
// Deterministic: no randomness, stable sorts.

const UC = {
  // text (widths only through TOKENS.font.metrics)
  CHAR_W: TOKENS.font.metrics.label, DETAIL_W: TOKENS.font.metrics.detail, TITLE_W: TOKENS.font.metrics.title,
  LABEL_W: TOKENS.font.metrics.edgeLabel, WRAP_W: TOKENS.font.metrics.edgeWrap,
  TEXT_H: 18, DETAIL_H: 16, LABEL_LINE_H: 16,
  // ellipse
  WRAP: 156, MIN_W: 128, MIN_H: 44, PAD_TXT: 14, GRID: 4,
  LEVEL_K: { summary: 1.14, user: 1, subfunction: 0.86 },
  COMP_PAD: 10,                                  // compartment: 3 * COMP_PAD + one DETAIL_H per extension point
  // actors
  AVATAR: 56, ACTOR_WRAP: 120, NAME_GAP: 8, CAPTION_H: 16, ACTOR_MIN_W: 72,   // every actor: a round avatar, name (and «system» / «time») below
  ACTOR_GAP_Y: 24, ACTOR_CHILD_GAP: 44, ACTOR_GAP: 96,
  // subjects
  TITLE_H: 36, TITLE_PAD_X: 44, EMPTY_W: 240, PAD_X: 28, PAD_Y: 20, SUBJ_GAP: 32, EMPTY_BODY: 56,
  // placement
  ROW_GAP: 10, CHILD_GAP: 22, GAP_MIN: 84, GAP_MAX: 200, GAP_MEET_MAX: 400, GAP_PER_LABEL: 28, MARGIN: 40, BUCKET: 24, SWEEPS: 12, PASSES: 4, SWAP_PASSES: 3,
  // lines and labels
  CLEAR: 4, LABEL_GAP: 12, LABEL_H: 22, LABEL_X: 12, CURVE_OFFS: [0, 28, -28, 56, -56, 90, -90, 130, -130, 180, -180, 240, -240],
  W_CROSS: 100, W_HIT: 250, W_LEN: 0.01
};

const ucGrid = (v) => Math.ceil(v / UC.GRID) * UC.GRID;
const ucTextW = (t, cw) => Math.ceil(String(t == null ? '' : t).length * cw);
const ucR1 = (v) => Math.round(v * 10) / 10;

// The name wrapped to at most two lines: one line when it fits UC.WRAP, else the word split with the narrowest widest line.
function ucWrap(text, cw, limit) {
  const s = String(text == null ? '' : text).trim().replace(/\s+/g, ' ');
  if (ucTextW(s, cw) <= limit) return [s];
  const words = s.split(' ');
  if (words.length < 2) return [s];
  let best = null;
  for (let i = 1; i < words.length; i++) {
    const a = words.slice(0, i).join(' '), b = words.slice(i).join(' ');
    const w = Math.max(a.length, b.length);
    if (!best || w < best.w) best = { w, lines: [a, b] };
  }
  return best.lines;
}

// ---------- model ----------

function ucModel(data) {
  const actors = data.actors || [], cases = data.useCases || [], links = data.links || [];
  let subjects = data.subjects && data.subjects.length ? data.subjects : null;
  if (subjects) delete data._subjects;
  else subjects = data._subjects = [{ id: '_main', name: data.title || '' }];
  const m = { data, actors, cases, links, subjects, actorBy: {}, caseBy: {}, aIdx: {}, cIdx: {}, sIdx: {}, sz: {} };
  actors.forEach((a, i) => { m.actorBy[a.id] = a; m.aIdx[a.id] = i; });
  cases.forEach((c, i) => { m.caseBy[c.id] = c; m.cIdx[c.id] = i; });
  subjects.forEach((s, i) => { m.sIdx[s.id] = i; });
  m.si = {};                                        // case id -> subject index (unknown or missing: the first)
  cases.forEach((c) => { m.si[c.id] = m.sIdx[c.subject] !== undefined ? m.sIdx[c.subject] : 0; });
  m.subj = subjects.map((s, i) => ({ s, i, collapsed: s.collapsed === true, cases: [] }));
  cases.forEach((c) => m.subj[m.si[c.id]].cases.push(c));
  m.hidden = {};
  cases.forEach((c) => { m.hidden[c.id] = m.subj[m.si[c.id]].collapsed; });
  m.links = links.filter((l) => (m.actorBy[l.from] || m.caseBy[l.from]) && (m.actorBy[l.to] || m.caseBy[l.to]));
  m.colorRank = {};
  cases.forEach((c) => { if (c.color != null && m.colorRank[c.color] === undefined) m.colorRank[c.color] = Object.keys(m.colorRank).length; });
  // neighbours for the barycentre: actor <-> case, case <-> case through include and extend
  m.nbr = {};
  const add = (a, b) => { (m.nbr[a] = m.nbr[a] || []).push(b); (m.nbr[b] = m.nbr[b] || []).push(a); };
  m.links.forEach((l) => {
    if (l.from === l.to) return;
    const fa = !!m.actorBy[l.from], ta = !!m.actorBy[l.to];
    if (l.type === 'association' ? fa !== ta : (!fa && !ta)) add(l.from, l.to);
  });
  // a specialised use case is ordered next to its parent (it sits one column to the right of it)
  cases.forEach((c) => { if (c.parent && c.parent !== c.id && cases.some((x) => x.id === c.parent)) add(c.id, c.parent); });
  ucSides(m);
  return m;
}

function ucRoot(by, id) {                           // top of a `parent` chain (cycle safe)
  let cur = by[id], n = 0;
  while (cur && cur.parent && by[cur.parent] && n++ < 50) cur = by[cur.parent];
  return cur;
}

function ucSides(m) {
  m.side = {};
  m.actors.forEach((a) => {
    const r = ucRoot(m.actorBy, a.id) || a;
    let side = r.side === 'left' || r.side === 'right' ? r.side : null;
    if (!side) {
      let starts = false, ends = false;
      // a root and its descendants decide together
      m.actors.forEach((b) => {
        if ((ucRoot(m.actorBy, b.id) || b) !== r) return;
        m.links.forEach((l) => { if (l.type === 'association') { if (l.from === b.id) starts = true; else if (l.to === b.id) ends = true; } });
      });
      side = !starts && ends ? 'right' : 'left';
    }
    m.side[a.id] = side;
    a._side = side;
  });
}

// ---------- sizes ----------

function ucSizes(m) {
  m.actors.forEach((a) => {
    const kind = a.kind === 'system' || a.kind === 'time' ? a.kind : 'human';
    const lines = ucWrap(a.name, UC.CHAR_W, UC.ACTOR_WRAP);
    a._lines = lines;
    const tw = Math.max(...lines.map((l) => ucTextW(l, UC.CHAR_W)));
    a.w = ucGrid(Math.max(UC.ACTOR_MIN_W, tw + 8));
    a.h = ucGrid(UC.AVATAR + UC.NAME_GAP + lines.length * UC.TEXT_H + (kind === 'human' ? 0 : UC.CAPTION_H));
    a._figW = UC.AVATAR; a._figH = UC.AVATAR;
    m.sz[a.id] = { w: a.w, h: a.h, anchor: UC.AVATAR / 2 };
  });
  m.cases.forEach((c) => {
    if (m.hidden[c.id]) {
      c._lines = ucWrap(c.name, UC.CHAR_W, UC.WRAP); c._compH = 0; c._hidden = true; c.w = 0; c.h = 0;
      m.sz[c.id] = { w: 0, h: 0, anchor: 0 };
      return;
    }
    delete c._hidden;
    const lines = ucWrap(c.name, UC.CHAR_W, UC.WRAP);
    const tw = Math.max(...lines.map((l) => ucTextW(l, UC.CHAR_W)));
    const k = UC.LEVEL_K[c.level] || 1;
    // Every use case has the same corner radius _r, half a one-line height: a one-line use case is a pill, a taller one
    // (two lines, extension points) a rounded rectangle. The text needs the straight part plus a little of each end.
    const R = (UC.MIN_H * k) / 2;
    const h = (lines.length > 1 ? lines.length * UC.TEXT_H + 24 : UC.MIN_H) * k;
    let w = Math.max(UC.MIN_W * k, (tw + 2 * UC.PAD_TXT) * k + R);
    const pts = (c.extensionPoints || []).map(String);
    const compH = pts.length ? 2 * UC.COMP_PAD + pts.length * UC.DETAIL_H : 0;   // CSS pads the compartment COMP_PAD top and bottom
    if (pts.length) w = Math.max(w, Math.max(...pts.map((p) => ucTextW(p, UC.DETAIL_W))) + 2 * UC.PAD_TXT + R);
    c._lines = lines; c._compH = compH;
    c.w = ucGrid(w); c.h = ucGrid(h + compH); c._r = Math.min(R, c.h / 2, c.w / 2);
    m.sz[c.id] = { w: c.w, h: c.h, anchor: c.h / 2, r: c._r };
  });
}

// ---------- ranks and units ----------

function ucRanks(m) {
  m.rank = {};
  m.cases.forEach((c) => { m.rank[c.id] = 0; });
  const same = (a, b) => m.si[a] === m.si[b] && !m.hidden[a] && m.caseBy[a] && m.caseBy[b];
  const cons = [];                                  // [lo, hi, delta]: rank[hi] >= rank[lo] + delta, delta 0 both ways
  m.links.forEach((l) => {
    if (!m.caseBy[l.from] || !m.caseBy[l.to] || !same(l.from, l.to) || l.from === l.to) return;
    if (l.type === 'include') cons.push([l.from, l.to, 1]);
    else if (l.type === 'extend') cons.push([l.to, l.from, 1]);
  });
  // a use case's specialisations sit one column to the right of it, like what it includes, so their lines are short
  // curves into its side rather than hooks around each other
  m.cases.forEach((c) => { if (c.parent && m.caseBy[c.parent] && same(c.id, c.parent)) cons.push([c.parent, c.id, 1]); });
  const n = m.cases.length;
  for (let pass = 0, ch = true; ch && pass < n + 2; pass++) {
    ch = false;
    cons.forEach(([lo, hi, d]) => { if (m.rank[hi] < m.rank[lo] + d) { m.rank[hi] = m.rank[lo] + d; ch = true; } });
  }
  // a case only a right-side actor reaches (and nothing builds on) moves to the right-most column of its subject
  const succ = {}, grouped = {};
  cons.forEach(([lo, , d]) => { if (d === 1) succ[lo] = true; });
  m.cases.forEach((c) => { if (c.parent && m.caseBy[c.parent]) { grouped[c.id] = true; grouped[c.parent] = true; } });
  m.subj.forEach((sj) => {
    if (sj.collapsed) return;
    const movable = [], rest = [];
    sj.cases.forEach((c) => {
      const act = (m.nbr[c.id] || []).filter((id) => m.actorBy[id]);
      (act.length && act.every((id) => m.side[id] === 'right') && !succ[c.id] && !grouped[c.id] ? movable : rest).push(c);
    });
    if (!movable.length) return;
    const maxR = rest.length ? Math.max(...rest.map((c) => m.rank[c.id])) : -1;
    const target = rest.length ? Math.max(maxR, 1) : 0;
    movable.forEach((c) => { m.rank[c.id] = Math.max(m.rank[c.id], target); });
  });
}

// units: a root and its `parent` descendants stacked below it
function ucUnits(m) {
  m.unit = {};                                      // root id -> {id, members:[{id,off,anch}], H, actor}
  m.unitOf = {};                                    // any id -> root id
  const build = (list, by, childGap, isActor, valid) => {
    const kids = {};
    list.forEach((x) => { if (x.parent && by[x.parent] && valid(x, by[x.parent])) (kids[x.parent] = kids[x.parent] || []).push(x); });
    const seen = {};
    const make = (root) => {
      const members = []; let off = 0;
      const walk = (x) => {
        if (seen[x.id]) return; seen[x.id] = true;
        const z = m.sz[x.id];
        members.push({ id: x.id, off, anch: z.anchor, h: z.h });
        off += z.h + childGap;
        (kids[x.id] || []).forEach(walk);
        m.unitOf[x.id] = root.id;
      };
      walk(root);
      const last = members[members.length - 1];
      m.unit[root.id] = { id: root.id, members, H: last.off + last.h, actor: isActor };
    };
    list.forEach((x) => { if (!(x.parent && by[x.parent] && valid(x, by[x.parent]))) make(x); });
    list.forEach((x) => { if (!seen[x.id]) make(x); });   // parent cycles
  };
  build(m.actors, m.actorBy, UC.ACTOR_CHILD_GAP, true, (x, p) => m.side[x.id] === m.side[p.id]);
  build(m.cases, m.caseBy, UC.CHILD_GAP, false, (x, p) => m.si[x.id] === m.si[p.id] && !m.hidden[x.id] && m.rank[x.id] === m.rank[p.id]);
}

// ---------- columns (x) ----------

function ucColumns(m) {
  // label widths between adjacent ranks widen the gap
  const lab = (l) => ucLabelLines(l).w;
  m.colX = []; m.cols = [];                         // colX[s][rank] = {x, w}
  let maxContent = 0, leftW = 0, rightW = 0;
  m.actors.forEach((a) => { if (m.side[a.id] === 'left') leftW = Math.max(leftW, a.w); else rightW = Math.max(rightW, a.w); });
  m.leftW = leftW; m.rightW = rightW;
  m.subj.forEach((sj) => {
    const ranks = {};
    sj.cases.forEach((c) => { if (!m.hidden[c.id]) (ranks[m.rank[c.id]] = ranks[m.rank[c.id]] || []).push(c); });
    sj.ranks = Object.keys(ranks).map(Number).sort((a, b) => a - b);
    sj.rankCases = ranks;
    sj.colW = sj.ranks.map((r) => Math.max(...ranks[r].map((c) => c.w)));
    sj.gap = sj.ranks.map((r, k) => {
      if (k === sj.ranks.length - 1) return 0;
      let lw = 0, nl = 0;
      const meet = {};   // labels whose lines meet at one use case on either side of the gap need room one after another
      m.links.forEach((l) => {
        if ((l.type !== 'include' && l.type !== 'extend') || !m.caseBy[l.from] || !m.caseBy[l.to]) return;
        const rf = m.rank[l.from], rt = m.rank[l.to];
        if (m.si[l.from] !== sj.i || m.si[l.to] !== sj.i) return;
        if (Math.min(rf, rt) === r && Math.max(rf, rt) === sj.ranks[k + 1]) {
          lw = Math.max(lw, lab(l)); nl++;
          [l.from, l.to].forEach((id) => { (meet[id] = meet[id] || []).push(lab(l)); });
        }
      });
      const along = Math.max(0, ...Object.values(meet).filter((ws) => ws.length > 1).map((ws) => ws.reduce((a, b) => a + b, 0) + UC.LABEL_GAP * (ws.length + 1)));
      return Math.max(Math.min(UC.GAP_MAX, Math.max(UC.GAP_MIN, lw ? lw + 16 + UC.GAP_PER_LABEL * (nl - 1) : 0)), Math.min(UC.GAP_MEET_MAX, along));
    });
    // long or two-line labels of lines between use cases of one column pair need vertical room: a wider row gap
    let labH = 0;
    m.links.forEach((l) => {
      if ((l.type !== 'include' && l.type !== 'extend') || !m.caseBy[l.from] || !m.caseBy[l.to] || m.si[l.from] !== sj.i || m.si[l.to] !== sj.i) return;
      const t = ucLabelLines(l);
      if (t.h > UC.LABEL_H || t.w > UC.WRAP) labH = Math.max(labH, t.h);
    });
    sj.rowGap = labH ? UC.ROW_GAP + labH - UC.LABEL_H + UC.LABEL_GAP : UC.ROW_GAP;
    sj.content = sj.colW.reduce((s, w) => s + w, 0) + sj.gap.reduce((s, w) => s + w, 0);
    maxContent = Math.max(maxContent, sj.content);
  });
  const titleMin = Math.max(0, ...m.subj.map((sj) => ucTextW(sj.s.name, UC.TITLE_W) + UC.TITLE_PAD_X));
  const left = (leftW ? UC.MARGIN + leftW + UC.ACTOR_GAP : UC.MARGIN);
  const hasVis = m.subj.some((sj) => sj.ranks.length);
  m.W = Math.max(hasVis ? maxContent + 2 * UC.PAD_X : 0, titleMin);
  m.L = left;
  m.subj.forEach((sj) => {
    const out = [];
    // each subject keeps its own width: its columns are not stretched to the widest subject (left edges stay aligned)
    let x = m.L + UC.PAD_X;
    sj.ranks.forEach((r, k) => {
      out[r] = { x, w: sj.colW[k] };
      x += sj.colW[k] + sj.gap[k];
    });
    m.colX[sj.i] = out;
  });
  m.R = m.L + m.W;
  m.actors.forEach((a) => {
    a.x = m.side[a.id] === 'left' ? UC.MARGIN + Math.floor((leftW - a.w) / 2) : m.R + UC.ACTOR_GAP + Math.floor((rightW - a.w) / 2);
  });
  m.cases.forEach((c) => {
    if (m.hidden[c.id]) { c.x = m.L; return; }
    const col = m.colX[m.si[c.id]][m.rank[c.id]];
    c.x = col.x + Math.floor((col.w - c.w) / 2);
  });
}

// ---------- link text ----------

function ucLabelLines(l) {
  if (l.type !== 'include' && l.type !== 'extend') return { lines: [], w: 0, h: 0 };
  const lines = ['«' + l.type + '»'];
  let w = ucTextW(lines[0], UC.LABEL_W);
  if (l.condition) {
    const cond = ucWrap('[' + l.condition + ']', UC.WRAP_W, 150);
    cond.forEach((s) => { lines.push(s); w = Math.max(w, ucTextW(s, UC.WRAP_W)); });
  }
  return { lines, w: w + 2 * UC.LABEL_X, h: lines.length > 1 ? UC.LABEL_H + (lines.length - 1) * UC.LABEL_LINE_H : UC.LABEL_H };
}

// ---------- geometry helpers ----------

// the item's box and anchor for a line: ellipse, actor (figure) or the title bar of a collapsed subject
function ucItem(m, id) {
  const a = m.actorBy[id];
  if (a) {
    const human = a.kind !== 'system' && a.kind !== 'time';
    const fw = a._figW, fh = a._figH;
    return { kind: 'actor', id, cx: a.x + a.w / 2, cy: a.y + m.sz[id].anchor, box: { x: a.x + (a.w - fw) / 2, y: a.y, w: fw, h: fh }, whole: { x: a.x, y: a.y, w: a.w, h: a.h }, human };
  }
  const c = m.caseBy[id];
  if (!c) return null;
  if (m.hidden[id]) {
    const b = m.bars[m.si[id]];
    return { kind: 'bar', id, cx: b.x + b.w / 2, cy: b.y + b.h / 2, box: b, whole: b };
  }
  return { kind: 'case', id, cx: c.x + c.w / 2, cy: c.y + c.h / 2, a: c.w / 2, b: c.h / 2, r: c._r };
}

function ucClip(it, tx, ty, whole) {                // the point where the ray from the item's anchor toward (tx, ty) leaves it
  const dx = tx - it.cx, dy = ty - it.cy;
  if (!dx && !dy) return [it.cx, it.cy];
  if (it.kind === 'case') {                        // where the ray leaves the use case: bisect on the distance to its core
    const c = ucCore(it), L = Math.hypot(dx, dy), ux = dx / L, uy = dy / L;
    let lo = 0, hi = it.a + it.b;
    for (let k = 0; k < 30; k++) { const mid = (lo + hi) / 2; if (ucPtCore([it.cx + ux * mid, it.cy + uy * mid], c) < c.r) lo = mid; else hi = mid; }
    return [it.cx + ux * lo, it.cy + uy * lo];
  }
  if (it.kind === 'actor' && !whole) {               // the avatar is a circle: end the line just off its rim
    const t = (it.box.w / 2 + 3) / Math.hypot(dx, dy);
    return [it.cx + dx * t, it.cy + dy * t];
  }
  const r = whole ? it.whole : it.box;
  let t = Infinity;
  if (dx > 0) t = Math.min(t, (r.x + r.w - it.cx) / dx); else if (dx < 0) t = Math.min(t, (r.x - it.cx) / dx);
  if (dy > 0) t = Math.min(t, (r.y + r.h - it.cy) / dy); else if (dy < 0) t = Math.min(t, (r.y - it.cy) / dy);
  if (!(t >= 0) || t === Infinity) t = 0;
  return [it.cx + dx * t, it.cy + dy * t];
}

// A use case is a rounded rectangle with corner radius r (a pill when r is half its height): every point within r of
// its core, the rectangle inset by r. e = {cx, cy, a, b, r} (half width, half height, radius). The ...Ellipse names
// are kept from the first version, when use cases were ellipses.
function ucCore(e) {
  const r = Math.min(e.r || Math.min(e.a, e.b), e.a, e.b), hx = e.a - r, hy = e.b - r;
  return { r, x0: e.cx - hx, y0: e.cy - hy, x1: e.cx + hx, y1: e.cy + hy };
}
function ucPtSeg(p, a, b) {
  const dx = b[0] - a[0], dy = b[1] - a[1], d2 = dx * dx + dy * dy;
  const t = d2 ? Math.max(0, Math.min(1, ((p[0] - a[0]) * dx + (p[1] - a[1]) * dy) / d2)) : 0;
  return Math.hypot(p[0] - a[0] - t * dx, p[1] - a[1] - t * dy);
}
function ucSegSeg(p, q, a, b) {                    // distance between two segments (0 when they cross)
  if (ucSegCross(p, q, a, b)) return 0;
  return Math.min(ucPtSeg(p, a, b), ucPtSeg(q, a, b), ucPtSeg(a, p, q), ucPtSeg(b, p, q));
}
function ucPtCore(p, c) {                          // distance from a point to the core rectangle
  const dx = Math.max(c.x0 - p[0], 0, p[0] - c.x1), dy = Math.max(c.y0 - p[1], 0, p[1] - c.y1);
  return Math.hypot(dx, dy);
}
function ucSegCore(p, q, c) {                      // distance from a segment to the core rectangle
  if (ucPtCore(p, c) === 0 || ucPtCore(q, c) === 0) return 0;
  const k = [[c.x0, c.y0], [c.x1, c.y0], [c.x1, c.y1], [c.x0, c.y1]];
  return Math.min(...k.map((v, i) => ucSegSeg(p, q, v, k[(i + 1) % 4])));
}
function ucSegEllipse(p, q, e, inflate) {          // does segment p-q enter the use case (inflated)?
  const c = ucCore(e);
  return ucSegCore(p, q, c) < c.r + inflate;
}

function ucSegRect(p, q, r) {                      // segment against a rectangle (sampled)
  for (let i = 0; i <= 12; i++) {
    const t = i / 12, x = p[0] + (q[0] - p[0]) * t, y = p[1] + (q[1] - p[1]) * t;
    if (x > r.x && x < r.x + r.w && y > r.y && y < r.y + r.h) return true;
  }
  return false;
}

const ucQuad = (p0, c, p1, t) => [(1 - t) * (1 - t) * p0[0] + 2 * (1 - t) * t * c[0] + t * t * p1[0], (1 - t) * (1 - t) * p0[1] + 2 * (1 - t) * t * c[1] + t * t * p1[1]];

const ucCubic = (p0, c1, c2, p1, t) => {
  const u = 1 - t, a = u * u * u, b = 3 * u * u * t, c = 3 * u * t * t, d = t * t * t;
  return [a * p0[0] + b * c1[0] + c * c2[0] + d * p1[0], a * p0[1] + b * c1[1] + c * c2[1] + d * p1[1]];
};
// A point at t (0..1) along a line: 2 points straight, 3 a quadratic curve, 4 a cubic curve (two control points)
function ucAt(pts, t) {
  if (pts.length === 4) return ucCubic(pts[0], pts[1], pts[2], pts[3], t);
  if (pts.length === 3) return ucQuad(pts[0], pts[1], pts[2], t);
  return [pts[0][0] + (pts[1][0] - pts[0][0]) * t, pts[0][1] + (pts[1][1] - pts[0][1]) * t];
}
function ucPolyline(pts) {
  if (pts.length === 3 || pts.length === 4) { const out = []; for (let i = 0; i <= 20; i++) out.push(ucAt(pts, i / 20)); return out; }   // 5+: an orthogonal path
  return pts;
}

function ucSegCross(a, b, c, d) {
  const o = (p, q, r) => (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0]);
  const d1 = o(a, b, c), d2 = o(a, b, d), d3 = o(c, d, a), d4 = o(c, d, b);
  return ((d1 > 0 && d2 < 0) || (d1 < 0 && d2 > 0)) && ((d3 > 0 && d4 < 0) || (d3 < 0 && d4 > 0));
}

// ---------- cost of an arrangement (straight lines) ----------

function ucCost(m, pos) {
  const ell = {};
  const nodes = {};
  m.cases.forEach((c) => {
    const z = m.sz[c.id];
    if (m.hidden[c.id]) { nodes[c.id] = { kind: 'bar', cx: pos.barX, cy: pos.y[c.id] }; return; }
    nodes[c.id] = { kind: 'case', cx: pos.x[c.id] + z.w / 2, cy: pos.y[c.id] + z.h / 2, a: z.w / 2, b: z.h / 2, r: z.r };
    ell[c.id] = nodes[c.id];
  });
  m.actors.forEach((a) => { nodes[a.id] = { kind: 'actor', cx: a.x + a.w / 2, cy: pos.y[a.id] + m.sz[a.id].anchor }; });
  const segs = [];
  m.links.forEach((l) => {
    const A = nodes[l.from], B = nodes[l.to];
    if (!A || !B || l.from === l.to) return;
    const p = A.kind === 'case' ? ucClip(A, B.cx, B.cy) : [A.cx, A.cy];
    const q = B.kind === 'case' ? ucClip(B, A.cx, A.cy) : [B.cx, B.cy];
    segs.push({ p, q, l });
  });
  let cross = 0, hits = 0, len = 0;
  const boxes = m.actors.map((a) => ({ id: a.id, x: a.x, y: pos.y[a.id], w: a.w, h: a.h }));
  segs.forEach((s) => {
    len += Math.hypot(s.q[0] - s.p[0], s.q[1] - s.p[1]);
    for (const id in ell) if (id !== s.l.from && id !== s.l.to && ucSegEllipse(s.p, s.q, ell[id], UC.CLEAR)) hits++;
    boxes.forEach((b) => { if (b.id !== s.l.from && b.id !== s.l.to && ucSegRect(s.p, s.q, b)) hits++; });
  });
  for (let i = 0; i < segs.length; i++) for (let j = i + 1; j < segs.length; j++) {
    const a = segs[i].l, b = segs[j].l;
    if (a.from === b.from || a.from === b.to || a.to === b.from || a.to === b.to) continue;
    if (ucSegCross(segs[i].p, segs[i].q, segs[j].p, segs[j].q)) cross++;
  }
  return { crossings: cross, hits, length: len, cost: cross * UC.W_CROSS + hits * UC.W_HIT + len * UC.W_LEN };
}

// ---------- 1-D placement (isotonic regression with separation) ----------

// items in order: {H, d (desired top), w (weight)}; returns tops. lo/hi bound the whole stack.
function ucPlace1(items, gap, lo, hi) {
  const n = items.length, off = [];
  let o = 0;
  items.forEach((it, i) => { off[i] = o; o += it.H + gap; });
  const total = o - gap;
  const blocks = [];
  items.forEach((it, i) => {
    blocks.push({ s: i, e: i, sw: it.w, swq: it.w * (it.d - off[i]) });
    while (blocks.length > 1) {
      const b = blocks[blocks.length - 1], a = blocks[blocks.length - 2];
      if (a.swq / a.sw <= b.swq / b.sw) break;
      a.e = b.e; a.sw += b.sw; a.swq += b.swq; blocks.pop();
    }
  });
  const tops = new Array(n);
  blocks.forEach((b) => {
    let q = Math.round(b.swq / b.sw);
    if (lo !== undefined) q = Math.max(q, lo);
    if (hi !== undefined) q = Math.min(q, hi - total);
    if (lo !== undefined && q < lo) q = lo;
    for (let i = b.s; i <= b.e; i++) tops[i] = q + off[i];
  });
  return tops;
}

// ---------- arrangement ----------

// where the unit wants to be: desired top and weight from its neighbours' current centres
// An actor sits in the middle (median) of the use cases it reaches, ignoring outliers: those in another subject than most.
function ucWant(m, u, cy) {
  let sw = 0, sd = 0;
  const ds = [], subj = [];
  u.members.forEach((mem) => {
    (m.nbr[mem.id] || []).forEach((nid) => {
      const y = cy(nid);
      if (y === undefined) return;
      const d = y - mem.off - mem.anch;
      sd += d; sw++;
      ds.push(d); subj.push(m.si[nid]);
    });
  });
  if (!sw) return null;
  if (!u.actor) return { d: sd / sw, w: sw };
  const cnt = {};
  subj.forEach((k) => { if (k !== undefined) cnt[k] = (cnt[k] || 0) + 1; });
  const top = Object.keys(cnt).sort((a, b) => cnt[b] - cnt[a] || a - b)[0];
  const keep = (top === undefined ? ds : ds.filter((_, i) => String(subj[i]) === top)).sort((a, b) => a - b);
  const h = keep.length >> 1;
  return { d: keep.length % 2 ? keep[h] : (keep[h - 1] + keep[h]) / 2, w: keep.length };
}

// Place everything for the given case column orders. Returns positions and the cost.
function ucArrangeOnce(m, orders, actorOrderIn, fixedActors) {
  const y = {}, xs = {};
  m.cases.forEach((c) => { xs[c.id] = c.x; });
  // subject bands
  let top = UC.MARGIN;
  const bands = m.subj.map((sj) => {
    const band = { top };
    if (sj.collapsed) { band.bodyTop = top + UC.TITLE_H / 2; band.bodyH = 0; top += UC.TITLE_H + UC.SUBJ_GAP; }
    else {
      let bodyH = 0;
      sj.ranks.forEach((r) => {
        const col = orders[sj.i][r];
        const h = col.reduce((s, id) => s + m.unit[id].H, 0) + Math.max(0, col.length - 1) * sj.rowGap;
        bodyH = Math.max(bodyH, h);
      });
      if (!sj.ranks.length) bodyH = UC.EMPTY_BODY;
      if (sj.s.fh) bodyH = Math.max(bodyH, sj.s.fh - UC.TITLE_H - 2 * UC.PAD_Y);
      band.bodyTop = top + UC.TITLE_H + UC.PAD_Y; band.bodyH = bodyH;
      top = band.bodyTop + bodyH + UC.PAD_Y + UC.SUBJ_GAP;
    }
    return band;
  });
  const barX = m.L + m.W / 2;
  // initial: columns centred in the body, hidden cases at the bar centre
  const unitTop = {};
  m.subj.forEach((sj) => {
    if (sj.collapsed) { m.barTop[sj.i] = bands[sj.i].top; sj.cases.forEach((c) => { y[c.id] = bands[sj.i].top + UC.TITLE_H / 2; }); return; }
    sj.ranks.forEach((r) => {
      const col = orders[sj.i][r];
      const h = col.reduce((s, id) => s + m.unit[id].H, 0) + Math.max(0, col.length - 1) * sj.rowGap;
      let t = bands[sj.i].bodyTop + Math.round((bands[sj.i].bodyH - h) / 2);
      col.forEach((id) => { unitTop[id] = t; t += m.unit[id].H + sj.rowGap; });
    });
  });
  const setUnit = (id, t) => { unitTop[id] = t; m.unit[id].members.forEach((mem) => { y[mem.id] = t + mem.off; }); };
  Object.keys(unitTop).forEach((id) => setUnit(id, unitTop[id]));
  const cy = (id) => {
    if (y[id] === undefined) return undefined;
    return y[id] + m.sz[id].anchor;
  };
  // actor stacks: initial order authored, then by desired
  const actorOrder = { left: [], right: [] };
  let aprev = actorOrderIn || null;
  const placeActors = (resort) => {
    ['left', 'right'].forEach((side) => {
      let ids = aprev ? aprev[side].slice() : m.actors.filter((a) => m.unit[a.id] && m.unit[a.id].actor && m.unitOf[a.id] === a.id && m.side[a.id] === side).map((a) => a.id);
      const want = {};
      ids.forEach((id) => { want[id] = ucWant(m, m.unit[id], cy); });
      if (resort && !fixedActors) {
        const key = (id) => (want[id] ? want[id].d + m.unit[id].H / 2 : (y[id] !== undefined ? y[id] + m.unit[id].H / 2 : 1e9));
        ids = ids.map((id, i) => ({ id, k: key(id), i })).sort((p, q) => p.k - q.k || p.i - q.i).map((p) => p.id);
      }
      let fall = UC.MARGIN;
      const items = ids.map((id) => {
        const wnt = want[id];
        const d = wnt ? wnt.d : (y[id] !== undefined ? y[id] : fall);
        fall += m.unit[id].H + UC.ACTOR_GAP_Y;
        return { H: m.unit[id].H, d, w: wnt ? wnt.w : 0.01 };
      });
      const tops = ucPlace1(items, UC.ACTOR_GAP_Y, UC.MARGIN);
      ids.forEach((id, i) => setUnit(id, tops[i]));
      actorOrder[side] = ids;
    });
    aprev = actorOrder;
  };
  placeActors(true);
  for (let pass = 0; pass < UC.PASSES; pass++) {
    m.subj.forEach((sj) => {
      if (sj.collapsed) return;
      const ranks = pass % 2 ? sj.ranks.slice().reverse() : sj.ranks;
      ranks.forEach((r) => {
        const col = orders[sj.i][r];
        const items = col.map((id) => {
          const u = m.unit[id], wnt = ucWant(m, u, cy);
          return { H: u.H, d: wnt ? wnt.d : unitTop[id], w: wnt ? wnt.w : 0.01 };
        });
        const lo = bands[sj.i].bodyTop, hi = lo + bands[sj.i].bodyH;
        const tops = ucPlace1(items, sj.rowGap, lo, hi);
        col.forEach((id, i) => setUnit(id, tops[i]));
      });
    });
    placeActors(true);
  }
  const res = { y, x: xs, bands, barX, orders, actorOrder };
  Object.assign(res, ucCost(m, res));
  return res;
}

const ucCloneOrders = (o) => o.map((s) => { const r = {}; Object.keys(s).forEach((k) => { r[k] = s[k].slice(); }); return r; });

// barycentre reorder of every column from the neighbours' centres in `res`, ties by colour then authored order
function ucReorder(m, res) {
  const cy = (id) => (res.y[id] === undefined ? undefined : res.y[id] + m.sz[id].anchor);
  const out = ucCloneOrders(res.orders);
  m.subj.forEach((sj) => {
    if (sj.collapsed) return;
    sj.ranks.forEach((r) => {
      const col = out[sj.i][r];
      const key = (id) => {
        const u = m.unit[id], w = ucWant(m, u, cy);
        return w ? w.d + u.H / 2 : res.y[id] + u.H / 2;
      };
      const colr = (id) => { const c = m.caseBy[id]; return c.color != null && m.colorRank[c.color] !== undefined ? m.colorRank[c.color] : 99; };
      out[sj.i][r] = col.map((id, i) => ({ id, k: Math.round(key(id) / UC.BUCKET), c: colr(id), a: m.cIdx[id], i }))
        .sort((p, q) => p.k - q.k || p.c - q.c || p.a - q.a).map((p) => p.id);
    });
  });
  return out;
}

function ucArrange(m) {
  ucUnits(m);
  const orders = m.subj.map((sj) => {
    const o = {};
    sj.ranks.forEach((r) => { o[r] = sj.rankCases[r].filter((c) => m.unitOf[c.id] === c.id).map((c) => c.id); });
    return o;
  });
  let cur = ucArrangeOnce(m, orders, null), best = cur;
  for (let i = 0; i < UC.SWEEPS; i++) {
    cur = ucArrangeOnce(m, ucReorder(m, cur), cur.actorOrder);
    if (cur.cost < best.cost - 1e-9) best = cur;
  }
  // adjacent swaps while the cost drops
  for (let pass = 0; pass < UC.SWAP_PASSES; pass++) {
    let improved = false;
    m.subj.forEach((sj) => sj.collapsed || sj.ranks.forEach((r) => {
      for (let i = 0; i + 1 < best.orders[sj.i][r].length; i++) {
        const o = ucCloneOrders(best.orders), col = o[sj.i][r];
        [col[i], col[i + 1]] = [col[i + 1], col[i]];
        const t = ucArrangeOnce(m, o, best.actorOrder, true);
        if (t.cost < best.cost - 1e-9) { best = t; improved = true; }
      }
    }));
    ['left', 'right'].forEach((side) => {
      for (let i = 0; i + 1 < best.actorOrder[side].length; i++) {
        const ao = { left: best.actorOrder.left.slice(), right: best.actorOrder.right.slice() }, col = ao[side];
        [col[i], col[i + 1]] = [col[i + 1], col[i]];
        const t = ucArrangeOnce(m, best.orders, ao, true);
        if (t.cost < best.cost - 1e-9) { best = t; improved = true; }
      }
    });
    if (!improved) break;
  }
  m.final = best;
  m.actors.forEach((a) => { a.y = best.y[a.id]; });
  m.cases.forEach((c) => { c.y = best.y[c.id]; });
}

// ---------- subject boxes, lines, labels, canvas ----------

function ucSubjects(m) {
  const vis = m.subj.filter((sj) => !sj.collapsed && sj.cases.length);
  const hid = m.cases.filter((c) => m.hidden[c.id]);
  const titleMin = Math.max(0, ...m.subj.map((sj) => ucTextW(sj.s.name, UC.TITLE_W) + UC.TITLE_PAD_X));
  let L, R;
  if (vis.length) {
    const cs = [].concat(...vis.map((sj) => sj.cases));
    L = Math.min(...cs.map((c) => c.x)) - UC.PAD_X; R = Math.max(...cs.map((c) => c.x + c.w)) + UC.PAD_X;
    if (R - L < titleMin) { const g = (titleMin - (R - L)) / 2; L -= g; R += g; }
  } else if (hid.length) { L = Math.min(...hid.map((c) => c.x)); R = L + titleMin; }
  else {
    let lw = 0;
    m.actors.forEach((a) => { if (m.side[a.id] === 'left') lw = Math.max(lw, a.w); });
    L = lw ? UC.MARGIN + lw + UC.ACTOR_GAP : UC.MARGIN; R = L + titleMin;
  }
  L = Math.round(L * 10) / 10; R = Math.round(R * 10) / 10;
  let prev = null;
  m.bars = [];
  m.subj.forEach((sj) => {
    const s = sj.s, ys = sj.cases.map((c) => c.y), top0 = prev === null ? UC.MARGIN : prev + UC.SUBJ_GAP;
    const own = sj.cases.filter((c) => !m.hidden[c.id]);
    // one left edge for every subject; each ends where its own use cases (or its title) end
    const ownTitle = ucTextW(s.name, UC.TITLE_W) + UC.TITLE_PAD_X;
    const ownR = own.length ? Math.max(...own.map((c) => c.x + c.w)) + UC.PAD_X : L + Math.max(ownTitle, UC.EMPTY_W);
    s.x = L; s.w = Math.round(Math.max(ownR - L, ownTitle, sj.collapsed ? 0 : s.fw || 0) * 10) / 10; s._titleH = UC.TITLE_H;
    if (sj.collapsed) {
      // layoutDiagram knows the bar's band; routeDiagram puts the bar where the expanded subject's top was (its use cases keep x/y)
      const bt = m.barTop[sj.i];
      s.y = typeof bt === 'number' ? bt : ys.length ? Math.round((Math.min(...ys) - UC.PAD_Y - UC.TITLE_H) * 10) / 10 : top0; s.h = UC.TITLE_H;
    } else if (own.length) {
      const t = Math.min(...own.map((c) => c.y)), b = Math.max(...own.map((c) => c.y + c.h));
      s.y = t - UC.PAD_Y - UC.TITLE_H; s.h = Math.max(b - t + 2 * UC.PAD_Y + UC.TITLE_H, s.fh || 0);
    } else { s.y = top0; s.h = Math.max(UC.TITLE_H + 2 * UC.PAD_Y + UC.EMPTY_BODY, s.fh || 0); }
    m.bars[sj.i] = { x: s.x, y: s.y, w: s.w, h: UC.TITLE_H };
    prev = s.y + s.h;
  });
}

function ucOverlapRect(a, b, pad) { return a.x < b.x + b.w + pad && b.x < a.x + a.w + pad && a.y < b.y + b.h + pad && b.y < a.y + a.h + pad; }
function ucRectEllipse(r, e, pad) {               // does the rectangle cover part of the use case (inflated)?
  const c = ucCore(e);
  const gx = Math.max(c.x0 - (r.x + r.w), 0, r.x - c.x1), gy = Math.max(c.y0 - (r.y + r.h), 0, r.y - c.y1);
  return Math.hypot(gx, gy) < c.r + pad;
}

function ucLines(m) {
  const items = {};
  m.actors.concat(m.cases).forEach((x) => { items[x.id] = ucItem(m, x.id); });
  const ellipses = m.cases.filter((c) => !m.hidden[c.id]).map((c) => items[c.id]);
  const obstacles = (a, b) => ({ ell: ellipses.filter((e) => e.id !== a && e.id !== b), rects: m.actors.filter((x) => x.id !== a && x.id !== b).map((x) => ({ id: x.id, x: x.x, y: x.y, w: x.w, h: x.h })) });
  const hitsOf = (pts, ob, actorPad = 0) => {
    const poly = ucPolyline(pts);
    let n = 0;
    for (let i = 0; i + 1 < poly.length; i++) {
      ob.ell.forEach((e) => { if (ucSegEllipse(poly[i], poly[i + 1], e, UC.CLEAR)) n++; });
      ob.rects.forEach((r) => {
        const rr = actorPad ? { x: r.x - actorPad, y: r.y - actorPad, w: r.w + 2 * actorPad, h: r.h + 2 * actorPad } : r;
        if (ucSegRect(poly[i], poly[i + 1], rr)) n++;
      });
    }
    return n;
  };
  // Precompute clear vertical and horizontal corridor coordinates from actual item boxes (works in both layoutDiagram and routeDiagram)
  const leftActors = m.actors.filter((a) => m.side[a.id] === 'left');
  const rightActors = m.actors.filter((a) => m.side[a.id] === 'right');
  const subjL = m.subj.length ? Math.min(...m.subj.map((sj) => sj.s.x)) : UC.MARGIN;
  const subjR = m.subj.length ? Math.max(...m.subj.map((sj) => sj.s.x + sj.s.w)) : UC.MARGIN + UC.EMPTY_W;
  const corridorX = [];
  if (leftActors.length) {
    const maxLA = Math.max(...leftActors.map((a) => a.x + a.w));
    if (subjL - maxLA > 16) corridorX.push((maxLA + subjL) / 2);
    corridorX.push(Math.max(12, Math.min(...leftActors.map((a) => a.x)) - 24));
  } else corridorX.push(Math.max(12, subjL - 24));
  if (rightActors.length) {
    const minRA = Math.min(...rightActors.map((a) => a.x));
    if (minRA - subjR > 16) corridorX.push((subjR + minRA) / 2);
    corridorX.push(Math.max(...rightActors.map((a) => a.x + a.w)) + 24);
  } else corridorX.push(subjR + 24);
  m.subj.forEach((sj) => {
    if (sj.collapsed) return;
    const ivs = sj.cases.filter((c) => !m.hidden[c.id]).map((c) => [c.x, c.x + c.w]).sort((a, b) => a[0] - b[0]);
    let cur = null;
    ivs.forEach(([x0, x1]) => {
      if (!cur) { cur = [x0, x1]; return; }
      if (x0 - cur[1] >= 24) {
        const gx = (cur[1] + x0) / 2;
        if (!corridorX.some((v) => Math.abs(v - gx) < 8)) corridorX.push(gx);
        cur = [x0, x1];
      } else cur[1] = Math.max(cur[1], x1);
    });
  });
  const corridorY = [UC.MARGIN / 2];
  for (let k = 0; k + 1 < m.subj.length; k++) {
    corridorY.push((m.subj[k].s.y + m.subj[k].s.h + m.subj[k + 1].s.y) / 2);
  }
  if (m.subj.length) {
    const last = m.subj[m.subj.length - 1].s;
    corridorY.push(last.y + last.h + 24);
  }
  const polyLen = (pts) => {
    let s = 0;
    for (let i = 0; i + 1 < pts.length; i++) s += Math.hypot(pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]);
    return s;
  };
  // straight, else the gentlest curve that clears every other ellipse and actor
  const route = (A, B, parent, bWhole = false) => {   // parent / bWhole: end on the whole actor (a generalization parent sits below its name)
    // A soft curve (cubic): it leaves A heading for B, so lines from one item fan out, and bends gently to enter B
    // along the main axis (sideways, or from above or below when B is mostly above or below A). When the plain curve
    // would cross an item, its bend moves sideways by `off`.
    const dx = B.cx - A.cx, dy = B.cy - A.cy, L = Math.hypot(dx, dy) || 1, nx = -dy / L, ny = dx / L;
    const flat = Math.abs(dx) >= Math.abs(dy) * 0.6, sx = Math.sign(dx) || 1, sy = Math.sign(dy) || 1;
    const kIn = Math.max(24, (flat ? Math.abs(dx) : Math.abs(dy)) * 0.5);
    const t2 = flat ? [B.cx - sx * kIn, B.cy] : [B.cx, B.cy - sy * kIn];
    const ob = obstacles(A.id, B.id);
    let best = null;
    for (const off of UC.CURVE_OFFS) {
      const p1 = ucClip(B, t2[0] + nx * off, t2[1] + ny * off, bWhole);
      const aim = [(A.cx + p1[0]) / 2 + nx * off, (A.cy + p1[1]) / 2 + ny * off];
      const p0 = ucClip(A, aim[0], aim[1], parent);
      const q1 = [p0[0] + (aim[0] - p0[0]) * 0.6, p0[1] + (aim[1] - p0[1]) * 0.6];
      const kk = Math.max(16, (flat ? Math.abs(p1[0] - p0[0]) : Math.abs(p1[1] - p0[1])) * 0.5);
      const q2 = flat ? [p1[0] - sx * kk, p1[1]] : [p1[0], p1[1] - sy * kk];
      const pts = [p0, q1, q2, p1];
      const h = hitsOf(pts, ob);
      if (!best || h < best.h) best = { pts, h };
      if (!h) break;
    }
    if (!best.h) return best;
    // Fallback for dense/tall columns: try opposite approach orientation, corridor S-curves, U-loops, and L-curves
    const cands = [];
    const altFlat = !flat, ak = Math.max(24, (altFlat ? Math.abs(dx) : Math.abs(dy)) * 0.5);
    const at2 = altFlat ? [B.cx - sx * ak, B.cy] : [B.cx, B.cy - sy * ak];
    for (const off of [...UC.CURVE_OFFS, 320, -320, 440, -440]) {
      const p1 = ucClip(B, at2[0] + nx * off, at2[1] + ny * off, bWhole);
      const aim = [(A.cx + p1[0]) / 2 + nx * off, (A.cy + p1[1]) / 2 + ny * off];
      const p0 = ucClip(A, aim[0], aim[1], parent);
      const q1 = [p0[0] + (aim[0] - p0[0]) * 0.6, p0[1] + (aim[1] - p0[1]) * 0.6];
      const kk = Math.max(16, (altFlat ? Math.abs(p1[0] - p0[0]) : Math.abs(p1[1] - p0[1])) * 0.5);
      const q2 = altFlat ? [p1[0] - sx * kk, p1[1]] : [p1[0], p1[1] - sy * kk];
      cands.push([p0, q1, q2, p1]);
    }
    if (Math.abs(dx) > 16) {
      const p0 = ucClip(A, A.cx + sx * 1e4, A.cy, parent);
      const p1 = ucClip(B, B.cx - sx * 1e4, B.cy, bWhole);
      const lo = Math.min(p0[0], p1[0]), hi = Math.max(p0[0], p1[0]);
      const xs = [0.5, 0.35, 0.65, 0.22, 0.78].map((f) => p0[0] + (p1[0] - p0[0]) * f)
        .concat(corridorX.filter((x) => x > lo + 8 && x < hi - 8));
      xs.forEach((xm) => cands.push([p0, [xm, p0[1]], [xm, p1[1]], p1]));
    }
    if (Math.abs(dy) > 16) {
      const p0 = ucClip(A, A.cx, A.cy + sy * 1e4, parent);
      const p1 = ucClip(B, B.cx, B.cy - sy * 1e4, bWhole);
      const lo = Math.min(p0[1], p1[1]), hi = Math.max(p0[1], p1[1]);
      const ys = [0.5, 0.35, 0.65, 0.22, 0.78].map((f) => p0[1] + (p1[1] - p0[1]) * f)
        .concat(corridorY.filter((y) => y > lo + 8 && y < hi - 8));
      ys.forEach((ym) => cands.push([p0, [p0[0], ym], [p1[0], ym], p1]));
    }
    [-1, 1].forEach((side) => {
      const p0 = ucClip(A, A.cx + side * 1e4, A.cy, parent);
      const p1 = ucClip(B, B.cx + side * 1e4, B.cy, bWhole);
      const base = side < 0 ? Math.min(p0[0], p1[0]) : Math.max(p0[0], p1[0]);
      const xs = [60, 100, 150, 220, 320, 450, 620].map((d) => base + side * d)
        .concat(corridorX.filter((x) => (side < 0 ? x < base - 12 : x > base + 12)));
      xs.forEach((xo) => cands.push([p0, [xo, p0[1]], [xo, p1[1]], p1]));
    });
    [-1, 1].forEach((side) => {
      const p0 = ucClip(A, A.cx, A.cy + side * 1e4, parent);
      const p1 = ucClip(B, B.cx, B.cy + side * 1e4, bWhole);
      const base = side < 0 ? Math.min(p0[1], p1[1]) : Math.max(p0[1], p1[1]);
      const ys = [60, 110, 180, 280, 420, 600, 850, 1150].map((d) => base + side * d)
        .concat(corridorY.filter((y) => (side < 0 ? y < base - 12 : y > base + 12)));
      ys.forEach((yo) => cands.push([p0, [p0[0], yo], [p1[0], yo], p1]));
    });
    for (const xm of corridorX) {
      for (const ym of corridorY) {
        const sxA = xm >= A.cx ? 1 : -1, syB = ym >= B.cy ? 1 : -1;
        cands.push([ucClip(A, A.cx + sxA * 1e4, A.cy, parent), [xm, ym], [B.cx, ym], ucClip(B, B.cx, B.cy + syB * 1e4, bWhole)]);
        const syA = ym >= A.cy ? 1 : -1, sxB = xm >= B.cx ? 1 : -1;
        cands.push([ucClip(A, A.cx, A.cy + syA * 1e4, parent), [A.cx, ym], [xm, ym], ucClip(B, B.cx + sxB * 1e4, B.cy, bWhole)]);
      }
    }
    let pick = { pts: best.pts, h: best.h, padH: hitsOf(best.pts, ob, 3), len: polyLen(best.pts) };
    for (const pts of cands) {
      const h = hitsOf(pts, ob);
      if (h > pick.h) continue;
      const padH = hitsOf(pts, ob, 3), len = polyLen(pts);
      if (h < pick.h || (h === pick.h && (padH < pick.padH || (padH === pick.padH && len < pick.len)))) {
        pick = { pts, h, padH, len };
      }
    }
    return { pts: pick.pts, h: pick.h };
  };
  let hits = 0;
  const placed = [];
  m.links.forEach((l) => {
    const A = items[l.from], B = items[l.to];
    delete l.labelBox; delete l._hidden;
    if (!A || !B || (A.kind === 'bar' && B.kind === 'bar' && m.si[l.from] === m.si[l.to]) || l.from === l.to) { l.points = []; l._hidden = true; return; }
    const r = route(A, B, false);
    hits += r.h;
    l.points = r.pts.map((p) => [ucR1(p[0]), ucR1(p[1])]);
  });
  // labels: on the line at the middle, slid along it and then off it until nothing is covered. Labels keep LABEL_GAP
  // between each other, and a label sitting on another line costs a little, so labels of converging lines spread out.
  const fixed = m.actors.map((a) => ({ x: a.x, y: a.y, w: a.w, h: a.h }));
  const lines = m.links.filter((l) => l.points && l.points.length >= 2).map((l) => ({ id: l.id, poly: ucPolyline(l.points) }));
  const onLines = (box, own) => lines.reduce((n, ln) => {
    if (ln.id === own) return n;
    for (let i = 0; i + 1 < ln.poly.length; i++) if (ucSegRect(ln.poly[i], ln.poly[i + 1], box)) return n + 1;
    return n;
  }, 0);
  const labelled = m.links.filter((l) => (l.type === 'include' || l.type === 'extend') && l.points.length);
  const candidates = (l, placed) => {
    const t = ucLabelLines(l), pts = l.points;
    const at = (u) => ucAt(pts, u);
    const score = (u, off) => {
      const p = at(u);
      const d = at(Math.min(1, u + 0.02)), e = at(Math.max(0, u - 0.02));
      const tx = d[0] - e[0], ty = d[1] - e[1], tl = Math.hypot(tx, ty) || 1;
      const box = { x: Math.round(p[0] - t.w / 2 - (ty / tl) * off), y: Math.round(p[1] - t.h / 2 + (tx / tl) * off), w: t.w, h: t.h };
      let s = 0;
      ellipses.forEach((el) => { if (ucRectEllipse(box, el, 2)) s += 4; });
      placed.forEach((o) => { if (ucOverlapRect(box, o, 2)) s += 40; else if (ucOverlapRect(box, o, UC.LABEL_GAP)) s += 3; });   // overlapping is never worth it
      fixed.forEach((o) => { if (ucOverlapRect(box, o, 0)) s += 4; });
      s += onLines(box, l.id) * 1;
      // stay on (or just beside) the own line, nearer its start: lines that meet at one use case are far apart there
      return { box, s: s + Math.abs(off) * 0.06 + Math.abs(u - 0.38) * 0.8 };
    };
    const tries = [];
    [0.38, 0.33, 0.43, 0.28, 0.48, 0.23, 0.53, 0.18, 0.58, 0.63, 0.13, 0.68, 0.73, 0.78, 0.83].forEach((u) => tries.push([u, 0]));
    [0.3, 0.55, 0.8, 1.2, 1.8, 2.5].forEach((k) => [1, -1].forEach((sg) => [0.38, 0.28, 0.48, 0.2, 0.58, 0.68].forEach((u) => tries.push([u, sg * t.h * k]))));
    return tries.map(([u, off]) => score(u, off)).sort((a, b) => a.s - b.s);   // stable: ties keep the try order
  };
  const placeLabel = (l, placed) => { const b = candidates(l, placed)[0]; l.labelBox = b.box; return b.s; };
  const othersOf = (l, skip) => labelled.filter((x) => x !== l && x !== skip).map((x) => x.labelBox);
  // first pass in link order; then twice more, each label placed again against where all the others ended up, so an
  // early label can move along its own line to make room for a later one (deterministic: fixed order, no randomness)
  labelled.forEach((l, i) => { placeLabel(l, labelled.slice(0, i).map((x) => x.labelBox)); });
  for (let pass = 0; pass < 2; pass++) labelled.forEach((l) => { placeLabel(l, othersOf(l)); });
  // a label still stuck (on another label, or pushed off its line): move one neighbour to another of its good places if
  // that lowers the two labels' total cost
  labelled.forEach((l) => {
    const now = candidates(l, othersOf(l))[0];
    if (now.s < 3) return;
    let best = null;
    labelled.forEach((o) => {
      if (o === l) return;
      const keep = o.labelBox, base = candidates(o, othersOf(o))[0].s + now.s;
      candidates(o, othersOf(o, l)).slice(0, 12).forEach((co) => {
        o.labelBox = co.box;
        const cl = candidates(l, othersOf(l))[0];
        const total = co.s + cl.s + (ucOverlapRect(co.box, cl.box, 2) ? 40 : 0);
        if (total < base - 1 && (!best || total < best.total)) best = { total, o, ob: co.box, lb: cl.box };
      });
      o.labelBox = keep;
    });
    if (best) { best.o.labelBox = best.ob; l.labelBox = best.lb; }
  });
  // generalization lines: the same soft curve as every other line, ending in the generalization triangle at the parent
  const parents = [];
  m.actors.forEach((a) => {
    if (!a.parent || !items[a.parent] || a.parent === a.id) return;
    const r = route(items[a.id], items[a.parent], false, true);
    hits += r.h;
    parents.push({ from: a.id, to: a.parent, kind: 'actor', points: r.pts.map((q) => [ucR1(q[0]), ucR1(q[1])]) });
  });
  m.cases.forEach((c) => {
    if (!c.parent || !items[c.parent] || c.parent === c.id) return;
    const a = items[c.id], p = items[c.parent];
    if (a.kind === 'bar' && p.kind === 'bar' && m.si[c.id] === m.si[c.parent]) return;
    const r = route(a, p, true, true);
    hits += r.h;
    parents.push({ from: c.id, to: c.parent, kind: 'useCase', points: r.pts.map((q) => [ucR1(q[0]), ucR1(q[1])]) });
  });
  m.data._parents = parents;
  m.hits = hits;
}

function ucCanvas(m) {
  let w = 0, h = 0;
  const grow = (x, y) => { w = Math.max(w, x); h = Math.max(h, y); };
  m.actors.forEach((a) => grow(a.x + a.w, a.y + a.h));
  m.cases.forEach((c) => { if (!m.hidden[c.id]) grow(c.x + c.w, c.y + c.h); });
  m.subj.forEach((sj) => grow(sj.s.x + sj.s.w, sj.s.y + sj.s.h));
  m.links.forEach((l) => { if (l.labelBox) grow(l.labelBox.x + l.labelBox.w, l.labelBox.y + l.labelBox.h); });
  // crossings of the drawn lines
  const polys = m.links.filter((l) => l.points && l.points.length).map((l) => ({ l, p: ucPolyline(l.points) }));
  let cross = 0;
  for (let i = 0; i < polys.length; i++) for (let j = i + 1; j < polys.length; j++) {
    const a = polys[i].l, b = polys[j].l;
    if (a.from === b.from || a.from === b.to || a.to === b.from || a.to === b.to) continue;
    let hit = false;
    for (let s = 0; s + 1 < polys[i].p.length && !hit; s++) for (let t = 0; t + 1 < polys[j].p.length && !hit; t++) hit = ucSegCross(polys[i].p[s], polys[i].p[s + 1], polys[j].p[t], polys[j].p[t + 1]);
    if (hit) cross++;
  }
  m.data.canvas = { width: Math.ceil(w + UC.MARGIN), height: Math.ceil(h + UC.MARGIN), crossings: cross, hits: m.hits };
}

function ucFinish(m) {
  ucSubjects(m);
  ucLines(m);
  ucCanvas(m);
}

function ucPrepare(data) {
  const m = ucModel(data);
  m.barTop = {};
  ucSizes(m);
  ucRanks(m);
  return m;
}

function layoutDiagram(data) {
  // A collapsed subject keeps its use cases where they would sit expanded (relative to the subject's top-left), so
  // expanding it brings them back instead of stacking them on the bar: lay out a copy with every subject open first.
  const subjects = data.subjects || [];
  let open = null;
  if (subjects.some((s) => s && s.collapsed === true)) {
    const copy = JSON.parse(JSON.stringify(data));
    copy.subjects.forEach((s) => { delete s.collapsed; });
    layoutDiagram(copy);
    open = { subj: {}, cases: {} };
    copy.subjects.forEach((s) => { open.subj[s.id] = s; });
    (copy.useCases || []).forEach((c) => { open.cases[c.id] = c; });
  }
  const m = ucPrepare(data);
  ucColumns(m);
  ucArrange(m);
  ucFinish(m);
  if (open) {
    m.cases.forEach((c) => {
      if (!m.hidden[c.id]) return;
      const s = m.subj[m.si[c.id]].s, os = open.subj[s.id], oc = open.cases[c.id];
      if (!os || !oc) return;
      c.x = Math.round((s.x + oc.x - os.x) * 10) / 10;
      c.y = Math.round((s.y + oc.y - os.y) * 10) / 10;
    });
  }
  return data;
}

function routeDiagram(data) {
  const m = ucPrepare(data);
  const num = (v) => typeof v === 'number' && isFinite(v);
  if (m.actors.concat(m.cases).some((x) => !num(x.x) || !num(x.y))) return layoutDiagram(data);
  m.final = null;
  // Subjects never overlap: when one grows into the next (a subject expanded, a use case dragged down), the
  // subjects below it move down with their use cases, keeping the gap. Nothing moves when they already clear.
  ucSubjects(m);
  let bottom = null, moved = false;
  m.subj.slice().sort((a, b) => a.s.y - b.s.y || a.i - b.i).forEach((sj) => {
    if (bottom !== null && sj.s.y < bottom + UC.SUBJ_GAP) {
      const dy = Math.round((bottom + UC.SUBJ_GAP - sj.s.y) * 10) / 10;
      sj.cases.forEach((c) => { c.y = Math.round((c.y + dy) * 10) / 10; });
      sj.s.y += dy;
      moved = true;
    }
    bottom = sj.s.y + sj.s.h;
  });
  if (moved) ucSubjects(m);
  ucLines(m);
  ucCanvas(m);
  return data;
}

// ── assets/shell/mermaid-flow.js ──
// Mermaid flowchart-family tokenizer, shared by the flowchart and use case importers (plan: dev/plans/plan-mermaid-input.md).
// Plain script: globals only, no DOM, no imports (it is concatenated with the type's mermaid.js).
//
// mmdParseFlow(text) returns the AST described in the plan ("mmdParseFlow(text) result"), with one additive field:
//   dirRaw: the direction word as written in the header ('TD', 'RL', ...) or null, so a caller can say that RL/BT were mapped.
// `ignored` entries are { line, text } with text starting with the statement keyword (style, classDef, click, ...).
// `shape` names: the bracket forms give rect, round, stadium, subroutine, cylinder, circle, dbl-circ, odd, diamond, hex,
// lean-r, lean-l, trap-b, trap-t. `@{ shape: x }` gives the canonical v11 name, with these exceptions where the plan
// gives no name: rectangle aliases -> rect, rounded -> round, pill/terminal -> stadium, hexagon/prepare -> hex,
// decision/question -> diamond, db/database/cylinder -> cyl, framed-rectangle/subprocess/fr-rect -> subproc; any other name
// is passed through lower-cased.
// A node that is only referenced gets shape 'rect' with label = id. The circ shapes (sm-circ, fr-circ, f-circ, dbl-circ)
// get an empty label when none is written.

const MMD_RESERVED = ['end', 'graph', 'subgraph', 'flowchart', 'style', 'class', 'classdef', 'linkstyle', 'click', 'default',
  'direction', 'call', 'href', 'interpolate', 'acctitle', 'accdescr',
  // sequenceDiagram keywords: Mermaid cannot parse them as participant ids, and every type shares one id rule
  'alt', 'else', 'opt', 'loop', 'par', 'and', 'rect', 'box', 'note', 'participant', 'actor', 'create', 'destroy', 'activate',
  'deactivate', 'autonumber', 'title', 'link', 'links', 'properties', 'details', 'critical', 'option', 'break', 'as', 'over', 'left',
  'right', 'of', 'off', 'sequencediagram'];

// Unescape label text: <br> to newline, then entities (#quot; #35; #59; #NNN;). One pass for the entities, so #35;quot; stays text.
function mmdText(s) {
  let t = String(s == null ? '' : s).trim();
  if (/^`[\s\S]*`$/.test(t)) t = t.slice(1, -1);
  t = t.replace(/<br\s*\/?>/gi, '\n');
  const named = { quot: '"', amp: '&', lt: '<', gt: '>', nbsp: ' ' };
  t = t.replace(/#(quot|amp|lt|gt|nbsp|\d+);/g, (m, k) => (k in named ? named[k] : String.fromCodePoint(+k)));
  return t.trim();
}

// Escape and quote a label for Mermaid. An empty label becomes a space, because Mermaid rejects "".
function mmdQuote(s) {
  const map = { '#': '#35;', '"': '#quot;', ';': '#59;', '`': '#96;' };
  const t = String(s == null ? '' : s).replace(/\r\n?/g, '\n').replace(/[#";`]/g, (c) => map[c]).replace(/\n/g, '<br>');
  return '"' + (t === '' ? ' ' : t) + '"';
}

// A Mermaid-safe id. `used` (a Set, optional) makes the result unique and records it.
function mmdSafeId(id, used) {
  let s = String(id == null ? '' : id).replace(/[^A-Za-z0-9_]+/g, '_') || 'n';
  if (/^[0-9]/.test(s)) s = 'n_' + s;
  while (MMD_RESERVED.includes(s.toLowerCase())) s += '_';
  if (used) {
    let u = s, k = 2;
    while (used.has(u)) u = s + '_' + k++;
    used.add(u);
    s = u;
  }
  return s;
}

const MMD_SHAPE_ALIASES = {
  rect: 'rect', rectangle: 'rect', proc: 'rect', process: 'rect', task: 'rect',
  rounded: 'round', event: 'round', stadium: 'stadium', pill: 'stadium', terminal: 'stadium',
  diamond: 'diamond', decision: 'diamond', question: 'diamond',
  doc: 'doc', document: 'doc', delay: 'delay',
  'sm-circ': 'sm-circ', 'small-circle': 'sm-circ', start: 'sm-circ',
  'fr-circ': 'fr-circ', 'framed-circle': 'fr-circ', stop: 'fr-circ',
  'f-circ': 'f-circ', 'filled-circle': 'f-circ', 'dbl-circ': 'dbl-circ', 'double-circle': 'dbl-circ',
  subproc: 'subproc', subprocess: 'subproc', 'fr-rect': 'subproc', 'framed-rectangle': 'subproc',
  cyl: 'cyl', cylinder: 'cyl', db: 'cyl', database: 'cyl', circle: 'circle', circ: 'circle',
  hex: 'hex', hexagon: 'hex', prepare: 'hex', 'lean-r': 'lean-r', 'lean-right': 'lean-r', 'in-out': 'lean-r',
  'lean-l': 'lean-l', 'lean-left': 'lean-l', 'out-in': 'lean-l', 'trap-b': 'trap-b', 'trapezoid-bottom': 'trap-b',
  priority: 'trap-b', 'trap-t': 'trap-t', 'trapezoid-top': 'trap-t', manual: 'trap-t',
};

// Bracket openers, longest first: [opener, family, closers [[closer, shape], ...]]. family = the bracket counted for nesting.
const MMD_OPENERS = [
  ['(((', '(', [[')))', 'dbl-circ']]],
  ['((', '(', [['))', 'circle']]],
  ['([', '(', [['])', 'stadium']]],
  ['(', '(', [[')', 'round']]],
  ['[[', '[', [[']]', 'subroutine']]],
  ['[(', '(', [[')]', 'cylinder']]],
  ['[/', '[', [['/]', 'lean-r'], ['\\]', 'trap-b']]],
  ['[\\', '[', [['\\]', 'lean-l'], ['/]', 'trap-t']]],
  ['[', '[', [[']', 'rect']]],
  ['{{', '{', [['}}', 'hex']]],
  ['{', '{', [['}', 'diamond']]],
  ['>', '[', [[']', 'odd']]],
];
const MMD_CLOSE_OF = { '(': ')', '[': ']', '{': '}' };
const MMD_ID = /[A-Za-z0-9_\u0080-￿]+(?:-(?=[A-Za-z0-9_\u0080-￿])[A-Za-z0-9_\u0080-￿]*)*/y;

// Split a line into statements at `;`, outside quotes and not when the `;` ends an entity such as #59;
function mmdSplitStatements(line) {
  const out = [];
  let cur = '', q = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (c === '"') q = !q;
    if (c === ';' && !q && !/#\w+$/.test(cur)) { out.push(cur); cur = ''; } else cur += c;
  }
  out.push(cur);
  return out.map((s) => s.trim()).filter(Boolean);
}

function mmdParseFlow(text) {
  const ast = { title: null, dir: null, dirRaw: null, directives: [], nodes: [], edges: [], subgraphs: [], ignored: [] };
  const nodeById = new Map(), sgById = new Map(), sgOf = new Map(), classOps = [];
  const stack = [];
  const lines = String(text == null ? '' : text).replace(/\r\n?/g, '\n').split('\n');
  let li = 0, headerSeen = false, ln = 0;
  const fail = (msg) => { throw new Error(`line ${ln}: ${msg}`); };

  // Front-matter
  while (li < lines.length && !lines[li].trim()) li++;
  if (li < lines.length && lines[li].trim() === '---') {
    li++;
    while (li < lines.length && lines[li].trim() !== '---') {
      const m = /^title\s*:\s*(.*)$/.exec(lines[li]);
      if (m) {
        let v = m[1].trim();
        if (v[0] === '"') { try { v = JSON.parse(v); } catch (e) { v = v.replace(/^"|"$/g, ''); } } else if (v[0] === "'") v = v.replace(/^'|'$/g, '');
        ast.title = mmdText(v);
      }
      li++;
    }
    li++;
  }

  function addNode(id, decl, classes) {
    let n = nodeById.get(id);
    if (!n) {
      n = { id, label: id, shape: 'rect', classes: [], line: ln, declared: false };
      nodeById.set(id, n);
      ast.nodes.push(n);
    }
    if (decl && !n.declared) { n.label = decl.label; n.shape = decl.shape; n.declared = true; }
    (classes || []).forEach((c) => { if (!n.classes.includes(c)) n.classes.push(c); });
    if (stack.length && !sgOf.has(id)) {
      const sg = stack[stack.length - 1];
      sgOf.set(id, sg.id);
      sg.nodes.push(id);
    }
    return id;
  }

  // Parse one node (id, then a shape or @{ } block, then :::classes) from s at i. Returns [id, next index].
  function parseNode(s, i) {
    while (s[i] === ' ') i++;
    MMD_ID.lastIndex = i;
    const m = MMD_ID.exec(s);
    if (!m) fail(`cannot read a node id near "${s.slice(i, i + 20)}"`);
    const id = m[0];
    i += id.length;
    let decl = null;
    if (s.startsWith('@{', i)) {
      let j = i + 2, q = false;
      while (j < s.length && (q || s[j] !== '}')) { if (s[j] === '"') q = !q; j++; }
      if (j >= s.length) fail('unterminated @{ }');
      const body = s.slice(i + 2, j);
      i = j + 1;
      const props = {};
      let part = '', pq = false;
      const flush = () => {
        const k = part.indexOf(':');
        if (k > 0) {
          let v = part.slice(k + 1).trim();
          if (/^(".*"|'.*')$/.test(v)) v = v.slice(1, -1);
          props[part.slice(0, k).trim().replace(/^"|"$/g, '')] = v;
        }
        part = '';
      };
      for (const c of body) { if (c === '"') pq = !pq; if (c === ',' && !pq) flush(); else part += c; }
      flush();
      const sname = String(props.shape || 'rect').toLowerCase();
      const shape = MMD_SHAPE_ALIASES[sname] || sname;
      const circ = ['sm-circ', 'fr-circ', 'f-circ', 'dbl-circ'].includes(shape);
      decl = { shape, label: 'label' in props ? mmdText(props.label) : (circ ? '' : id) };
    } else {
      for (const [open, fam, closers] of MMD_OPENERS) {
        if (!s.startsWith(open, i)) continue;
        let j = i + open.length;
        while (s[j] === ' ') j++;
        const tryClose = (k) => closers.find(([c]) => s.startsWith(c, k));
        let label = null, hit = null, end = 0;
        if (s[j] === '"') {
          const e = s.indexOf('"', j + 1);
          if (e > 0) {
            let k = e + 1;
            while (s[k] === ' ') k++;
            hit = tryClose(k);
            if (hit) { label = s.slice(j + 1, e); end = k + hit[0].length; }
          }
        }
        if (!hit) {
          const closeCh = MMD_CLOSE_OF[fam];
          let depth = 0, k = j;
          for (; k < s.length; k++) {
            if (depth === 0 && (hit = tryClose(k))) break;
            if (s[k] === fam) depth++; else if (s[k] === closeCh && depth > 0) depth--;
          }
          if (!hit) fail(`missing "${closers[0][0]}" for node ${id}`);
          label = s.slice(j, k);
          end = k + hit[0].length;
        }
        decl = { shape: hit[1], label: mmdText(label) };
        i = end;
        break;
      }
    }
    const classes = [];
    while (s.startsWith(':::', i)) {
      const m2 = /^[\w-]+/.exec(s.slice(i + 3));
      if (!m2) fail('empty class after :::');
      classes.push(m2[0]);
      i += 3 + m2[0].length;
    }
    return [addNode(id, decl, classes), i];
  }

  function parseLink(s, i) {
    let r = s.slice(i), m, id = null;
    if ((m = /^[A-Za-z0-9_]+@(?=[-=.~<ox])/.exec(r))) { id = m[0].slice(0, -1); r = r.slice(m[0].length); }
    let start = '';
    if ((m = /^([<ox])(?=[-=])/.exec(r))) { start = m[1]; r = r.slice(1); }
    let stroke, head = '', label = null;
    const take = (n) => { r = r.slice(n); };
    const textForm = (open, endRe, str) => {
      take(open);
      const e = endRe.exec(r);
      if (!e) fail('unterminated edge text');
      label = r.slice(0, e.index).trim().replace(/^"([\s\S]*)"$/, '$1');
      head = e[0].slice(-1);
      if (!'>ox'.includes(head)) head = '';
      take(e.index + e[0].length);
      stroke = str;
    };
    if ((m = /^~{3,}/.exec(r))) { stroke = 'invisible'; take(m[0].length); } else if (/^==\s/.test(r)) textForm(2, /={2,}[>ox]?/, 'thick');
    else if (/^-\.\s/.test(r)) textForm(2, /\.+-[>ox]?/, 'dotted');
    else if (/^--\s/.test(r)) textForm(2, /-{2,}[>ox]?/, 'normal');
    else if ((m = /^={2,}([>ox]?)/.exec(r))) { stroke = 'thick'; head = m[1]; take(m[0].length); } else if ((m = /^-\.+-([>ox]?)/.exec(r))) { stroke = 'dotted'; head = m[1]; take(m[0].length); } else if ((m = /^-{2,}([>ox]?)/.exec(r))) { stroke = 'normal'; head = m[1]; take(m[0].length); } else return null;
    if ((m = /^\s*\|/.exec(r))) {
      take(m[0].length);
      let e;
      if (/^\s*"/.test(r)) { const q = r.indexOf('"'); const q2 = r.indexOf('"', q + 1); e = r.indexOf('|', q2 + 1); label = r.slice(q + 1, q2); } else { e = r.indexOf('|'); label = r.slice(0, e); }
      if (e < 0) fail('unterminated |edge text|');
      take(e + 1);
    }
    const heads = { '>': 'arrow', o: 'circle', x: 'cross', '': 'none' };
    return { link: { label: label == null ? '' : mmdText(label), stroke, head: heads[head], both: start !== '', id }, next: s.length - r.length };
  }

  function parseChain(s) {
    let i = 0, prev = null;
    for (;;) {
      const group = [];
      for (;;) {
        const [id, j] = parseNode(s, i);
        group.push(id);
        i = j;
        while (s[i] === ' ') i++;
        if (s[i] === '&') { i++; continue; }
        break;
      }
      if (prev) prev.links.forEach((lk) => prev.group.forEach((a) => group.forEach((b) => ast.edges.push({ from: a, to: b, label: lk.label, stroke: lk.stroke, head: lk.head, both: lk.both, line: ln }))));
      if (i >= s.length) return;
      const res = parseLink(s, i);
      if (!res) fail(`cannot read "${s.slice(i, i + 20)}"`);
      i = res.next;
      prev = { group, links: [res.link] };
    }
  }

  // A repeated id under another parent is a separate subgraph (the same lane inside a `sub_` block); `sub` names the
  // top-level `sub_` block a subgraph sits in (flowcharts), else null.
  const sgScoped = new Map();
  function parseSubgraph(rest) {
    let id, title, m;
    if ((m = /^([^\s\[\]"]+)\s*\[([\s\S]*)\]$/.exec(rest))) { id = m[1]; title = m[2].trim().replace(/^"([\s\S]*)"$/, '$1'); } else if ((m = /^"([\s\S]*)"$/.exec(rest))) { id = title = m[1]; } else { id = title = rest; }
    title = mmdText(title);
    const top = stack.length ? stack[stack.length - 1] : null, parent = top ? top.id : null;
    const key = parent + '>' + id;
    const known = sgScoped.get(key) || (sgById.has(id) && sgById.get(id).parent === parent ? sgById.get(id) : null);
    if (known) { stack.push(known); return; }
    const sg = { id, title, parent, sub: !top && /^sub_/.test(id) ? id : (top ? top.sub : null), nodes: [], classes: [], line: ln };
    sgScoped.set(key, sg);
    if (!sgById.has(id)) sgById.set(id, sg);
    ast.subgraphs.push(sg);
    stack.push(sg);
  }

  function statement(s) {
    let m;
    if ((m = /^subgraph(?:\s+([\s\S]*))?$/.exec(s))) return parseSubgraph((m[1] || '').trim());
    if (s === 'end') { stack.pop(); return; }
    if (/^direction\s+\w+$/.test(s)) return;
    if ((m = /^class\s+(\S+)\s+(\S+)$/.exec(s))) { classOps.push([m[1].split(','), m[2].split(',')]); return; }
    if ((m = /^(classDef|style|linkStyle|click|accTitle|accDescr|href|call)\b/.exec(s))) { ast.ignored.push({ line: ln, text: s }); return; }
    parseChain(s);
  }

  let inAcc = false;
  for (; li < lines.length; li++) {
    ln = li + 1;
    const raw = lines[li].trim();
    if (inAcc) { if (raw.includes('}')) inAcc = false; continue; }
    if (!raw) continue;
    if (raw.startsWith('%%')) {
      const m = /^%%\s*@(\w+)\s*(.*)$/.exec(raw);
      if (m) ast.directives.push({ key: m[1], args: m[2].trim(), line: ln });
      continue;
    }
    if (/^accDescr\s*\{/.test(raw) && !raw.includes('}')) { inAcc = true; ast.ignored.push({ line: ln, text: raw }); continue; }
    let stmts = mmdSplitStatements(raw);
    if (!headerSeen) {
      const m = /^(?:flowchart|graph)(?:-elk)?(?:\s+(LR|RL|TB|TD|BT))?\s*(.*)$/.exec(stmts[0]);
      if (!m) fail('expected "flowchart" or "graph"');
      headerSeen = true;
      if (m[1]) { ast.dirRaw = m[1]; ast.dir = { LR: 'LR', RL: 'LR', TB: 'TB', TD: 'TB', BT: 'TB' }[m[1]]; }
      stmts = (m[2] ? [m[2]] : []).concat(stmts.slice(1));
    }
    stmts.forEach(statement);
  }
  if (!headerSeen) { ln = 1; fail('expected "flowchart" or "graph"'); }

  classOps.forEach(([ids, cls]) => ids.forEach((id) => {
    const target = nodeById.get(id) || sgById.get(id);
    if (target) cls.forEach((c) => { if (!target.classes.includes(c)) target.classes.push(c); });
  }));
  ast.nodes.forEach((n) => delete n.declared);
  return ast;
}

// ── assets/types/usecase/mermaid.js ──
// Use case <-> Mermaid. Plain script, no DOM, no imports; concatenated after assets/shell/mermaid-flow.js
// (needs mmdParseFlow, mmdQuote, mmdSafeId). Mapping: dev/plans/plan-mermaid-input.md, "Use case".
// Mermaid has no use case type, so the diagram is a flowchart marked `%% @type usecase`: inside a subgraph is a
// use case, outside is an actor (with no subgraph at all: stadium, circle and ellipse nodes are use cases).

// Returns a function raw id -> unique JSON/Mermaid id. Uniqueness is also enforced here, whatever mmdSafeId does with `used`.
function ucmIdMaker() {
  const used = new Set(), taken = new Set(), map = new Map();
  return raw => {
    raw = String(raw);
    if (!map.has(raw)) {
      let s = mmdSafeId(raw, used);
      const base = s;
      for (let i = 2; taken.has(s); i++) s = base + '_' + i;
      taken.add(s);
      map.set(raw, s);
    }
    return map.get(raw);
  };
}

// "a; b rest" style directive arguments -> [[id, rest], ...]; the first word may be several ids joined by commas.
function ucmItems(args) {
  return String(args || '').split(';').map(s => s.trim()).filter(Boolean).map(s => {
    const m = /^(\S+)\s*([\s\S]*)$/.exec(s);
    return [m[1].split(',').filter(Boolean), m[2].trim()];
  });
}

function ucmList(s) { return s.split(',').map(x => x.trim()).filter(Boolean); }

function fromMermaid(text) { return fromMermaidAst(mmdParseFlow(text)); }

function fromMermaidAst(ast) {
  const infos = [], warnings = [];
  const sid = ucmIdMaker();

  const seen = new Set();
  (ast.ignored || []).forEach(g => {
    if (/^classDef\s+c[1-8]\s/.test(g.text)) return;
    const kind = String(g.text || '').trim().split(/\s+/)[0];
    if (!seen.has(kind)) { seen.add(kind); infos.push('[INFO] line ' + g.line + ': "' + kind + '" is not used by use case diagrams, ignored'); }
  });
  if (ast.dir === 'TB') infos.push('[INFO] direction TB ignored: use case diagrams are laid out by --layout');

  // Subjects: top-level subgraphs. A node belongs to its innermost subgraph; a nested one flattens into the top-level subject.
  const subs = ast.subgraphs || [];
  const subById = new Map(subs.map(g => [g.id, g]));
  const topOf = g => { while (g.parent != null && subById.has(g.parent)) g = subById.get(g.parent); return g; };
  const nodeSub = new Map();
  subs.forEach(g => g.nodes.forEach(n => { if (!nodeSub.has(n)) nodeSub.set(n, topOf(g)); }));
  const hasSub = subs.length > 0;
  if (subs.some(g => g.parent != null)) infos.push('[INFO] nested subgraphs flattened into their top-level subject');

  const nodeById = new Map(ast.nodes.map(n => [n.id, n]));
  const edgesOf = new Map();
  ast.edges.forEach(e => [e.from, e.to].forEach(id => { if (!edgesOf.has(id)) edgesOf.set(id, []); edgesOf.get(id).push(e); }));

  // Notes: a flag-shaped node whose edges are all unlabelled and dotted.
  const isNote = n => n.shape === 'odd' && (edgesOf.get(n.id) || []).every(e => !e.label && e.stroke === 'dotted');
  const kind = new Map();   // Mermaid id -> 'note' | 'uc' | 'actor'
  ast.nodes.forEach(n => {
    kind.set(n.id, isNote(n) ? 'note' : (hasSub ? nodeSub.has(n.id) : ['stadium', 'circle', 'ellipse'].includes(n.shape)) ? 'uc' : 'actor');
  });
  if (!hasSub && ast.nodes.length && ![...kind.values()].includes('actor')) {
    infos.push('[INFO] no subgraph and no actor: every node reads as a use case (stadium or circle); draw actors with another shape, or put the use cases in a subgraph');
  }

  const data = { diagramType: 'usecase' };
  if (ast.title) {
    let t = String(ast.title);
    if (/^".*"$/.test(t)) { try { t = JSON.parse(t); } catch (e) { /* keep as written */ } }
    data.title = t;
  }

  const subjects = subs.filter(g => g.parent == null).map(g => {
    const o = { id: sid(g.id), name: g.title || g.id };
    if (g.classes.includes('collapsed')) o.collapsed = true;
    return o;
  });
  const subjectOf = new Map(subjects.map((s, i) => [subs.filter(g => g.parent == null)[i].id, s]));
  const byId = new Map();   // JSON id -> actor or use case object
  const actors = [], useCases = [];
  const slot = n => { const c = n.classes.find(x => /^c[1-8]$/.test(x)); return c ? c.slice(1) : null; };
  ast.nodes.forEach(n => {
    const k = kind.get(n.id);
    if (k === 'note') return;
    const o = { id: sid(n.id), name: n.label };
    if (k === 'actor') {
      if (n.classes.includes('system')) o.kind = 'system'; else if (n.classes.includes('time')) o.kind = 'time';
    } else {
      if (hasSub) o.subject = subjectOf.get(nodeSub.get(n.id).id).id;
      if (n.classes.includes('subfunction')) o.level = 'subfunction'; else if (n.classes.includes('summary')) o.level = 'summary';
    }
    if (slot(n)) o.color = slot(n);
    if (n.classes.includes('abstract')) o.abstract = true;
    (k === 'actor' ? actors : useCases).push(o);
    byId.set(o.id, o);
  });
  const isUc = id => kind.get(id) === 'uc';
  const isActor = id => kind.get(id) === 'actor';

  // Edges.
  const links = [];
  const EXT = /^(?:(?:<<|«)\s*extend\s*(?:>>|»)\s*(?:\(([^)]*)\))?|(?:<<|«)?\s*extend\s*(?:\(([^)]*)\))?\s*(?:>>|»)?)\s*(?::\s*([\s\S]*))?$/i;
  const INC = /^(?:<<|«)?\s*include\s*(?:>>|»)?(?:\s*:\s*([\s\S]*))?$/i;
  ast.edges.forEach(e => {
    const kf = kind.get(e.from), kt = kind.get(e.to);
    if (!kf || !kt) { warnings.push('[WARN] line ' + e.line + ': edge ends at a subgraph or unknown node, ignored'); return; }
    if (kf === 'note' || kt === 'note' || e.stroke === 'invisible') return;
    const label = String(e.label || '').trim();
    const from = sid(e.from), to = sid(e.to);
    const where = 'line ' + e.line + ': ' + e.from + ' -> ' + e.to;
    let m, mi;
    if (/^is\s+an?$/i.test(label)) {
      if (kf !== kt) warnings.push('[WARN] ' + where + ' "is a" joins an actor and a use case; use two actors or two use cases');
      else if (byId.get(from).parent) warnings.push('[WARN] ' + where + ' "is a": ' + e.from + ' already has a parent');
      else byId.get(from).parent = to;
    } else if ((mi = INC.exec(label)) || (m = EXT.exec(label))) {
      const type = m ? 'extend' : 'include';
      if (kf !== 'uc' || kt !== 'uc') { warnings.push('[WARN] ' + where + ' ' + type + ' joins two use cases'); return; }
      const l = { id: 'l' + (links.length + 1), type, from, to };
      const cond = m ? (m[3] ? m[3].trim() : '') : (mi[1] ? mi[1].trim() : '');
      const ep = m && (m[1] || m[2]) ? (m[1] || m[2]).trim() : '';
      if (cond) l.condition = cond;
      if (ep) l.extensionPoint = ep;
      links.push(l);
    } else if (kf === kt) {
      warnings.push('[WARN] ' + where + ' joins two ' + (kf === 'uc' ? 'use cases' : 'actors') + ' without "include", "extend" or "is a"; label it or remove it');
    } else {
      links.push({ id: 'l' + (links.length + 1), type: 'association', from, to });   // an arrowhead comes only from `%% @navigable`
    }
  });

  // Notes.
  const notes = [];
  ast.nodes.forEach(n => {
    if (kind.get(n.id) !== 'note') return;
    const note = { id: sid(n.id), text: n.label, useCases: [], actors: [] };
    (edgesOf.get(n.id) || []).forEach(e => {
      const other = e.from === n.id ? e.to : e.from;
      if (isUc(other)) note.useCases.push(sid(other)); else if (isActor(other)) note.actors.push(sid(other));
    });
    if (!note.useCases.length && !note.actors.length) warnings.push('[WARN] line ' + n.line + ': note "' + n.id + '" is linked to nothing');
    if (!note.useCases.length) delete note.useCases;
    if (!note.actors.length) delete note.actors;
    notes.push(note);
  });

  // Directives.
  const target = (raw, key, line) => {
    const o = byId.get(sid(raw));
    if (!o || !kind.has(raw)) warnings.push('[WARN] line ' + line + ': @' + key + ' names unknown id "' + raw + '"');
    return o;
  };
  const colorKey = {};
  ast.directives.forEach(d => {
    const a = String(d.args || '').trim();
    let m;
    switch (d.key) {
      case 'type': if (a && a !== 'usecase') infos.push('[INFO] line ' + d.line + ': @type ' + a + ' ignored'); break;
      case 'colorKey': if ((m = /^(\S+)\s+(.+)$/.exec(a))) colorKey[m[1]] = m[2].trim(); break;
      case 'showRefs': data.showRefs = true; break;
      case 'showNotes': data.showNotes = true; break;
      case 'schemaVersion': if (!isNaN(Number(a))) data.schemaVersion = Number(a); break;
      case 'navigable':
        if ((m = /^(\S+)\s+(\S+)$/.exec(a))) {
          const l = links.find(x => x.type === 'association' && x.from === sid(m[1]) && x.to === sid(m[2]));
          if (l) l.navigable = true; else warnings.push('[WARN] line ' + d.line + ': @navigable names no association from "' + m[1] + '" to "' + m[2] + '"');
        } else warnings.push('[WARN] line ' + d.line + ': @navigable needs the two ends of an association');
        break;
      case 'color':   // a colour that is not a palette slot (slots are classes c1..c8)
        if ((m = /^(\S+)\s+(\S+)$/.exec(a))) { const o = target(m[1], 'color', d.line); if (o) o.color = m[2]; }
        break;
      case 'refs': case 'points':
        ucmItems(a).forEach(([ids, rest]) => ids.forEach(id => {
          const o = target(id, d.key, d.line);
          if (o && rest) o[d.key === 'refs' ? 'refs' : 'extensionPoints'] = ucmList(rest);
        }));
        break;
      case 'side':
        if ((m = /^(\S+)\s+(left|right)$/i.exec(a))) { const o = target(m[1], 'side', d.line); if (o && kind.get(m[1]) === 'actor') o.side = m[2].toLowerCase(); }
        else warnings.push('[WARN] line ' + d.line + ': @side needs an id and left or right');
        break;
      case 'size':
        if ((m = /^(\S+)\s+(\d+(?:\.\d+)?)\s+(\d+(?:\.\d+)?)$/.exec(a))) {
          const s = subjectOf.get(m[1]);
          if (s) { if (+m[2] > 0) s.fw = +m[2]; if (+m[3] > 0) s.fh = +m[3]; } else warnings.push('[WARN] line ' + d.line + ': @size names unknown subject "' + m[1] + '"');
        } else warnings.push('[WARN] line ' + d.line + ': @size needs a subject, a width and a height');
        break;
      case 'level':
        if ((m = /^(\S+)\s+(user|subfunction|summary)$/i.exec(a))) { const o = target(m[1], 'level', d.line); if (o && kind.get(m[1]) === 'uc') o.level = m[2].toLowerCase(); }
        break;
      case 'note':
        if ((m = /^(\S+?):\s*([\s\S]+)$/.exec(a))) {
          const o = target(m[1], 'note', d.line);
          if (o) notes.push(kind.get(m[1]) === 'uc' ? { id: 'n' + (notes.length + 1), text: m[2].trim(), useCases: [o.id] } : { id: 'n' + (notes.length + 1), text: m[2].trim(), actors: [o.id] });
        }
        break;
      default: infos.push('[INFO] line ' + d.line + ': unknown directive @' + d.key + ' ignored');
    }
  });

  if (Object.keys(colorKey).length) data.colorKey = colorKey;
  if (subjects.length) data.subjects = subjects;
  data.actors = actors;
  data.useCases = useCases;
  data.links = links;
  if (notes.length) data.notes = notes;
  return { data, infos, warnings };
}

function toMermaid(data, opts) {
  opts = opts || {};
  const sid = ucmIdMaker();
  const subjects = data.subjects || [], actors = data.actors || [], useCases = data.useCases || [];
  subjects.forEach(s => sid(s.id));
  actors.forEach(a => sid(a.id));
  useCases.forEach(u => sid(u.id));
  const allIds = new Set([...subjects, ...actors, ...useCases].map(x => x.id));
  const q = s => mmdQuote(String(s == null ? '' : s));
  const slotOf = x => (/^[1-8]$/.test(String(x.color)) ? 'c' + x.color : null);
  const classesOf = (x, isUc) => [slotOf(x),
    isUc ? (x.level === 'subfunction' || x.level === 'summary' ? x.level : null) : (x.kind === 'system' || x.kind === 'time' ? x.kind : null),
    x.abstract ? 'abstract' : null].filter(Boolean);

  const out = [];
  if (data.title) out.push('---', 'title: ' + (/[:#"'\[\]{}&*!|>%@`,]|^[\s?-]|\s$/.test(data.title) ? JSON.stringify(String(data.title)) : data.title), '---');
  out.push('%% @type usecase');
  if (data.schemaVersion != null) out.push('%% @schemaVersion ' + data.schemaVersion);
  Object.keys(data.colorKey || {}).sort((a, b) => a - b).forEach(k => out.push('%% @colorKey ' + k + ' ' + data.colorKey[k]));
  if (data.showRefs) out.push('%% @showRefs');
  if (data.showNotes) out.push('%% @showNotes');
  out.push('flowchart LR');

  const multi = []; // [id, classes] of nodes that need `class` lines
  const node = (x, isUc, ind) => {
    const id = sid(x.id), cl = classesOf(x, isUc);
    if (cl.length > 1) multi.push([id, cl]);
    return ind + id + (isUc ? '([' : '[') + q(x.name) + (isUc ? '])' : ']') + (cl.length === 1 ? ':::' + cl[0] : '');
  };
  actors.forEach(a => out.push(node(a, false, '  ')));
  if (subjects.length) {
    subjects.forEach((s, i) => {
      out.push('  subgraph ' + sid(s.id) + '[' + q(s.name) + ']');
      // With one subject, a use case that names none sits in it; with several, one that names none goes to the first.
      useCases.filter(u => (u.subject && subjects.some(x => x.id === u.subject) ? u.subject : subjects[0].id) === s.id).forEach(u => out.push(node(u, true, '    ')));
      out.push('  end');
      if (s.collapsed) multi.push([sid(s.id), ['collapsed']]);
    });
  } else useCases.forEach(u => out.push(node(u, true, '  ')));

  [actors, useCases].forEach(list => list.forEach(x => { if (x.parent && [...actors, ...useCases].some(y => y.id === x.parent)) out.push('  ' + sid(x.id) + ' -->|is a| ' + sid(x.parent)); }));
  const known = new Set([...actors, ...useCases].map(x => x.id));
  const navigable = [];
  (data.links || []).forEach(l => {
    if (!known.has(l.from) || !known.has(l.to)) return;
    const a = sid(l.from), b = sid(l.to);
    if (l.type === 'include') out.push('  ' + a + ' -.->|' + (l.condition ? q('«include»: ' + l.condition) : '«include»') + '| ' + b);
    else if (l.type === 'extend') out.push('  ' + a + ' -.->|' + q('«extend»' + (l.extensionPoint ? ' (' + l.extensionPoint + ')' : '') + (l.condition ? ': ' + l.condition : '')) + '| ' + b);
    else { out.push('  ' + a + ' --- ' + b); if (l.navigable) navigable.push('  %% @navigable ' + a + ' ' + b); }
  });
  out.push(...navigable);
  [...actors, ...useCases].forEach(x => { if (x.color != null && !slotOf(x)) out.push('  %% @color ' + sid(x.id) + ' ' + x.color); });
  (data.notes || []).forEach(n => {
    const ends = [...(n.useCases || []), ...(n.actors || [])].filter(id => known.has(id)).map(sid);
    out.push('  ' + sid(allIds.has(n.id) ? 'note_' + n.id : n.id) + '>' + q(n.text) + ']' + (ends.length ? ' -.- ' + ends.join(' & ') : ''));
  });

  // `:::` takes one class and is not allowed on a subgraph, so the rest go through `class` lines, one per class.
  const byClass = new Map();
  multi.forEach(([id, cl]) => cl.forEach(c => { if (!byClass.has(c)) byClass.set(c, []); byClass.get(c).push(id); }));
  byClass.forEach((ids, c) => out.push('  class ' + ids.join(',') + ' ' + c));

  const list = (key, id, arr) => { if (arr && arr.length) out.push('%% @' + key + ' ' + sid(id) + ' ' + arr.join(', ')); };
  useCases.forEach(u => { list('refs', u.id, u.refs); list('points', u.id, u.extensionPoints); });
  actors.forEach(a => { if (a.side === 'left' || a.side === 'right') out.push('%% @side ' + sid(a.id) + ' ' + a.side); });
  subjects.forEach(s => { if (s.fw || s.fh) out.push('%% @size ' + sid(s.id) + ' ' + (s.fw || 0) + ' ' + (s.fh || 0)); });

  if (opts.palette) {
    const slots = new Set();
    [...actors, ...useCases].forEach(x => { if (slotOf(x)) slots.add(+x.color); });
    [...slots].sort((a, b) => a - b).forEach(n => { if (opts.palette[n - 1]) out.push('  classDef c' + n + ' fill:' + opts.palette[n - 1]); });
  }
  return out.join('\n') + '\n';
}

return { layoutDiagram, routeDiagram, fromMermaid, toMermaid };
}
